const option = (id, text) => ({ id, text });

const q = (id, theme, type, question, options, answers, explanation, source = "general") => ({
  id,
  theme,
  type,
  question,
  options: Object.entries(options).map(([key, value]) => option(key, value)),
  answers,
  explanation,
  source,
});

const o = (id, theme, question, expectedPoints, sampleAnswer, source = "general") => ({
  id,
  theme,
  question,
  expectedPoints,
  sampleAnswer,
  source,
});

